CREATE TABLE IF NOT EXISTS ai_credentials(workspace_id TEXT NOT NULL,provider TEXT NOT NULL,secret TEXT NOT NULL,PRIMARY KEY(workspace_id,provider));
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL,client_id TEXT,workspace_id TEXT NOT NULL DEFAULT 'demo');
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),expires TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,title TEXT NOT NULL,client_id TEXT NOT NULL,client_name TEXT NOT NULL,location TEXT NOT NULL,jd TEXT NOT NULL,criteria TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,mode TEXT NOT NULL,created_at TEXT NOT NULL,workspace_id TEXT NOT NULL DEFAULT 'demo');
CREATE TABLE IF NOT EXISTS candidates(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT,text TEXT NOT NULL,profile TEXT NOT NULL,file_path TEXT,file_hash TEXT UNIQUE,text_hash TEXT UNIQUE,consent TEXT NOT NULL,created_at TEXT NOT NULL,workspace_id TEXT NOT NULL DEFAULT 'demo');
CREATE TABLE IF NOT EXISTS applications(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES jobs(id),candidate_id TEXT NOT NULL REFERENCES candidates(id) ON DELETE CASCADE,stage TEXT NOT NULL DEFAULT 'Sourced',score TEXT,score_version INTEGER NOT NULL DEFAULT 0,score_error TEXT,submitted_at TEXT,reason TEXT,interview_at TEXT,created_at TEXT NOT NULL,UNIQUE(job_id,candidate_id),submitted_version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS views(user_id TEXT REFERENCES users(id),application_id TEXT REFERENCES applications(id) ON DELETE CASCADE,version INTEGER NOT NULL,viewed_at TEXT NOT NULL,PRIMARY KEY(user_id,application_id));
CREATE TABLE IF NOT EXISTS batches(id TEXT PRIMARY KEY,job_id TEXT REFERENCES jobs(id),consent TEXT NOT NULL,created_at TEXT NOT NULL,workspace_id TEXT NOT NULL DEFAULT 'demo');
CREATE TABLE IF NOT EXISTS batch_items(id TEXT PRIMARY KEY,batch_id TEXT REFERENCES batches(id),filename TEXT NOT NULL,file_path TEXT,file_hash TEXT,status TEXT NOT NULL,error TEXT,candidate_id TEXT REFERENCES candidates(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS audit(id BIGSERIAL PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,subject TEXT,detail TEXT,created_at TEXT NOT NULL,workspace_id TEXT NOT NULL DEFAULT 'demo');
CREATE TABLE IF NOT EXISTS weekly_reviews(week TEXT PRIMARY KEY,actor TEXT NOT NULL,notes TEXT NOT NULL,snapshot TEXT NOT NULL,created_at TEXT NOT NULL,workspace_id TEXT NOT NULL DEFAULT 'demo');
CREATE TABLE IF NOT EXISTS workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS clients(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS google_identities(subject TEXT PRIMARY KEY,user_id TEXT UNIQUE REFERENCES users(id));
CREATE TABLE IF NOT EXISTS invitations(token TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,client_id TEXT NOT NULL,email TEXT NOT NULL,expires TEXT NOT NULL,used_at TEXT);
CREATE TABLE IF NOT EXISTS oauth_requests(state TEXT PRIMARY KEY,browser_hash TEXT NOT NULL,verifier TEXT NOT NULL,nonce TEXT NOT NULL,invite TEXT,expires TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reset_tokens(token TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),expires TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_rate_limits(key TEXT PRIMARY KEY,hits INTEGER NOT NULL,reset_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS upload_sessions(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,job_id TEXT NOT NULL,actor TEXT NOT NULL,consent TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'uploading',expires TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS upload_files(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES upload_sessions(id) ON DELETE CASCADE,filename TEXT NOT NULL,pathname TEXT UNIQUE NOT NULL,size INTEGER NOT NULL,blob_url TEXT,content_type TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workflow_outbox(workspace_id TEXT PRIMARY KEY,requested_at TEXT NOT NULL,dispatched_at TEXT,run_id TEXT);
ALTER TABLE workflow_outbox ADD COLUMN IF NOT EXISTS run_id TEXT;
CREATE INDEX IF NOT EXISTS jobs_workspace ON jobs(workspace_id);
CREATE INDEX IF NOT EXISTS candidates_workspace ON candidates(workspace_id);
CREATE INDEX IF NOT EXISTS batches_workspace ON batches(workspace_id);
CREATE INDEX IF NOT EXISTS batch_items_queue ON batch_items(status,batch_id);
